import { boards } from '../common/api';
/**
 * Board data for widgets, at module level.
 *
 * 🚨 Widget hosts re-create their widgets on every redraw, so a widget that
 * fetched in `oninit` would ask again forever. Widgets only say what they
 * want; the store asks once, for every widget on the page together (one
 * request per period and size), and keeps the answer for five minutes.
 */
const TTL = 5 * 60 * 1000;
const cache = new Map();
const asked = new Set();
let queued = [];
let scheduled = false;
const key = (kind, period, limit) => `${kind}|${kind === 'now' ? '' : period}|${limit}`;

/** The rows, or undefined while they are on their way. */
export function want(kind, period, limit) {
  const k = key(kind, period, limit);
  const hit = cache.get(k);
  if ((!hit || Date.now() - hit.at > TTL) && !asked.has(k)) {
    asked.add(k);
    queued.push({
      kind,
      period,
      limit
    });
    if (!scheduled) {
      scheduled = true;
      setTimeout(flush, 0);
    }
  }
  return hit?.rows;
}
function flush() {
  scheduled = false;
  const groups = new Map();
  queued.splice(0).forEach(({
    kind,
    period,
    limit
  }) => {
    const g = `${period}|${limit}`;
    if (!groups.has(g)) groups.set(g, {
      kinds: [],
      period,
      limit
    });
    groups.get(g).kinds.push(kind);
  });
  groups.forEach(({
    kinds,
    period,
    limit
  }) => {
    boards(kinds, period, limit).then(res => kinds.forEach(kind => cache.set(key(kind, period, limit), {
      at: Date.now(),
      rows: res.data[kind] || []
    }))).catch(() => kinds.forEach(kind => cache.set(key(kind, period, limit), {
      at: Date.now(),
      rows: []
    }))).finally(() => {
      kinds.forEach(kind => asked.delete(key(kind, period, limit)));
      m.redraw();
    });
  });
}