import app from 'flarum/common/app';
const api = path => app.forum.attribute('apiUrl') + path;
export const profile = userId => app.request({
  method: 'GET',
  url: api(`/rotation/users/${userId}`)
});
export const savePrefs = prefs => app.request({
  method: 'PATCH',
  url: api('/rotation/me'),
  body: {
    data: prefs
  }
});
export const disconnect = () => app.request({
  method: 'DELETE',
  url: api('/rotation/me')
});
export const boards = (kinds, period, limit) => app.request({
  method: 'GET',
  url: api('/rotation/charts'),
  params: {
    kinds: kinds.join(','),
    period,
    limit
  }
});
export const connectUrl = () => app.forum.attribute('baseUrl') + '/rotation/connect/lastfm';
flarum.reg.add('ernestdefoe-rotation', 'common/api', { profile: profile,savePrefs: savePrefs,disconnect: disconnect,boards: boards,connectUrl: connectUrl, });